# -*- coding: utf-8 -*-
"""Наряд «чисті промпти» (25.09.2026): довжина КОЖНОГО промпту моделей — символи й токени. Промпти будує сам код:
міст (паспорт на трьох сценах стенда, руки 1–4, вибір, опис; ремонт і повнота — для довідки, їх править Т-7), JS
показу через node (помічниця, довідка, додаток паспорта, колір людини, приміряння) і жнива. TOKENIZER=<tokenizer.json>
[,<tokenizer.json>] — лічба ними (qwen3.5, gemma-4); без нього — символи. `cd джерела && python3 проби/промпти_довжина.py`"""
import json, os, re, subprocess, sys
sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
import bridge as B, жнива_промпти as Ж
ТОК = [__import__("tokenizers").Tokenizer.from_file(т) for т in os.environ.get("TOKENIZER", "").split(",") if т]
д = lambda ім, т: print("%-44s %6d симв" % (ім, len(т)) + "".join(" · %6d т" % len(к.encode(т).ids) for к in ТОК))
js, міст = open("показ.html", encoding="utf-8").read(), lambda ім, **в: json.loads(B.виклик(ім, json.dumps(в, ensure_ascii=False)))
шмат = lambda ім: re.search(r"^(?:const|function) %s\b.*?(?=^(?:const|let|function|async function|/\*)\b)" % ім, js, re.S | re.M).group(0)
код = "\n".join(шмат(і) for і in "ПРОМПТ_КОЛІР ШІ_ДОВІДКА ШІ_ПРОМПТ_ПОМІЧНИКА додатокДоПаспортаП ПРИМІРКА_СПІЛЬНЕ ПРИМІРКА_СПІЛЬНЕ_МАКІЯЖ "
                "примірка_спільне примірка_за_фото примірка_за_описом ПРИМІРКА_ОДИН_КАДР".split()).replace("const ", "var ")
П = json.loads(subprocess.run(["node", "-e", "const vm=require('vm'),к={станДляШі:()=>''};vm.createContext(к);vm.runInContext("
    "require('fs').readFileSync(0,'utf8'),к);console.log(JSON.stringify({колір:к.ПРОМПТ_КОЛІР,помічниця:к.ШІ_ПРОМПТ_ПОМІЧНИКА,"
    "довідка:к.ШІ_ДОВІДКА,додаток:к.додатокДоПаспортаП(),за_фото:к.примірка_за_фото(''),за_описом:к.примірка_за_описом(''),"
    "кадр:к.ПРИМІРКА_ОДИН_КАДР}))"], input=код, capture_output=True, text=True, check=True).stdout)
for ім, сл in (("типовий", "робочий день в офісі, дрес-код business casual, без підборів"), ("весілля", "в суботу весілля подруги "
               "з пʼятої вечора, ресторан, хочу щось легке"), ("Ір", "для авто та на урок, надворі дощ. Можна яскравий верх — куртку "
               "чи жакет, не темного кольору")):
    пп = міст("паспорт", сценарій={}, вимоги=сл, історія=[dict(хто="людина", текст=сл)])["промпт"]
    д("паспорт · " + ім, пп); д("паспорт · %s + додаток показу" % ім, пп + "\n\n" + П["додаток"])
д("додаток паспорта без довідки", П["додаток"].replace(П["довідка"], "")); д("довідка застосунку (ШІ_ДОВІДКА)", П["довідка"])
д("помічниця (роль, без довідки й стану)", П["помічниця"]); д("колір людини (ПРОМПТ_КОЛІР)", П["колір"])
for к in ("за_фото", "за_описом", "кадр"): д("приміряння · " + к, П[к])
вх = dict(json.load(open("стенд_вх.json", encoding="utf-8")), варіантів=10, ремонт_варіантів=5, бюджет_символів=120000, без_фото=1)
r = міст("запити", **вх); вимоги = lambda т: "\n".join(json.loads(т)["завдання"]["вимоги"])
for р in "1234": д("рука " + р, r["руки"][р])
for р in "12": д("рука %s · лише завдання.вимоги" % р, вимоги(r["руки"][р]))
пул = json.loads(r["руки"]["1"])["пул"]; н = lambda с, k: пул[с][k % len(пул[с])]["н"]
образи = [dict(ід="о%d" % (і + 1), підпис="задум %d" % і, речі=[н("верх", і), н("низ", і), н("взуття", і)]
               + ([н("сумка", і), н("прикраси", і)] if і % 2 else [])) for і in range(10)]
в = міст("від_моделі", текст_моделі=json.dumps(dict(версія="1", образи=образи), ensure_ascii=False), **вх)
for к in ("промпт_ремонту", "промпт_повноти", "промпт_лише_вибору", "промпт_вибору"):
    if в.get(к): д(к + ("  (Т-7, не правлю)" if к in ("промпт_ремонту", "промпт_повноти") else ""), в[к])
о = міст("опис", **dict(вх, речі=[сл[0]["id"] for сл in r["кандидати"].values() if сл][:6]))
д("вибір · лише завдання.вимоги", вимоги(в["промпт_лише_вибору"])); д("опис (ОПИС_V1)", о["промпт"]); д("опис · лише завдання.вимоги", вимоги(о["промпт"]))
for ім in ("ПРОМПТ_АРКУШ", "ПРОМПТ_ОДЯГ", "ПРОМПТ_ВЗУТТЯ", "ПРОМПТ_СУМКА", "ПРОМПТ_ПРИКРАСА", "ПРОМПТ_ДРІБНЕ"): д("жнива · " + ім, getattr(Ж, ім))
